INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-01','Diode Forward Voltage','Easy','ECE','arena','interpret','Electronic Components','multiple_choice','A silicon PN junction diode''s forward voltage drop at room temperature is approximately:','{"choices": ["0.2 V", "1.2 V", "0.7 V", "0.3 V"], "correct": 2}'::jsonb,'Silicon diode: V_f ≈ 0.6–0.7 V. Germanium: ≈ 0.3 V. Schottky: ≈ 0.2–0.4 V. LED: 1.8–3.5 V (depending on colour). The forward voltage arises from the contact potential of the PN junction.','{multiple_choice}'::text[],0.9) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-02','BJT Operating Regions','Easy','ECE','arena','select','Electronic Components','multiple_choice','A BJT transistor used as a switch should operate in which two regions?','{"choices": ["Active and Saturation", "Cut-off and Active", "Saturation and Cut-off", "Active and Breakdown"], "correct": 2}'::jsonb,'Switch OFF = Cut-off (I_B ≈ 0, I_C ≈ 0, V_CE ≈ V_CC). Switch ON = Saturation (maximum I_C, V_CE ≈ 0.2 V). Active region is for linear amplification. Breakdown is destructive.','{multiple_choice}'::text[],0.87) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-03','MOSFET Enhancement Mode Operation','Easy','ECE','arena','interpret','Electronic Components','multiple_choice','An N-channel enhancement-mode MOSFET is OFF when V_GS = 0 V. To turn it ON, V_GS must be:','{"choices": ["Negative (< 0 V)", "0 V", "Greater than V_GS(th)", "Greater than V_DS"], "correct": 2}'::jsonb,'Enhancement-mode N-MOSFET: normally OFF at V_GS=0. Channel forms when V_GS > V_GS(th) (typically 2–4 V). Depletion-mode MOSFETs are normally ON (channel exists at V_GS=0). PMOS requires V_GS < V_GS(th) (negative threshold).','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-04','Capacitor Colour Code (Film Type)','Easy','ECE','arena','interpret','Electronic Components','multiple_choice','A ceramic capacitor is marked "104". Its capacitance in picofarads is:','{"choices": ["104 pF", "10.4 pF", "1000 pF (1 nF)", "100,000 pF (100 nF)"], "correct": 3}'::jsonb,'"104" means 10 × 10⁴ pF = 100,000 pF = 100 nF = 0.1 µF. The first two digits are significant figures; the third digit is the power of 10 multiplier. "103" = 10,000 pF = 10 nF.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-05','Resistor Colour Code','Easy','ECE','arena','calculate','Electronic Components','multiple_choice','A resistor has bands: Orange, Orange, Red, Gold. What is its value and tolerance?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-06','Zener Diode Voltage Regulation','Easy','ECE','arena','predict','Electronic Components','multiple_choice','A 5.1 V Zener diode is connected in reverse bias with a series resistor. It provides:','{"choices": ["Variable voltage depending on current", "Approximately 5.1 V regulated output regardless of load variations (within specified current range)", "5.1 V only at one specific current", "A rectified output"], "correct": 1}'::jsonb,'Zener diodes maintain approximately constant voltage in reverse breakdown (V_Z = 5.1 V). As load current changes, Zener current adjusts to maintain V_Z. The series resistor limits total current.','{multiple_choice}'::text[],0.84) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-07','LED Current Limiting Resistor','Easy','ECE','arena','calculate','Electronic Components','multiple_choice','A red LED (V_f = 2.0 V, I_f = 20 mA) is powered from 5 V. Calculate the series resistor needed.
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-08','Inductors: Energy Storage','Easy','ECE','arena','predict','Electronic Components','multiple_choice','When current through an inductor is suddenly interrupted (switch opens), what happens?','{"choices": ["Current immediately drops to zero", "A large voltage spike is generated (flyback voltage) — the inductor maintains current flow, generating V = L × dI/dt; this can destroy semiconductor switches", "The inductor discharges safely through itself", "Voltage drops linearly"], "correct": 1}'::jsonb,'V = L × dI/dt. Sudden interruption → very large dI/dt → very large V (opposite to normal polarity). This "inductive kick" or flyback can exceed hundreds of volts. Flyback diodes (freewheeling diodes) clamp this in motor/relay drivers.','{multiple_choice}'::text[],0.83) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-09','Thyristor (SCR) Turn-Off','Medium','ECE','arena','predict','Electronic Components','multiple_choice','An SCR (Silicon Controlled Rectifier) is conducting. The gate signal is removed. What happens?','{"choices": ["The SCR turns off immediately when gate signal is removed", "The SCR continues conducting as long as anode current exceeds the holding current — the gate cannot turn off an SCR; it can only trigger it", "The SCR turns off on the next zero crossing", "The SCR reduces current by 50%"], "correct": 1}'::jsonb,'SCRs are latching devices — once triggered, they remain ON until anode current falls below holding current (I_H). In DC circuits, the circuit must be designed to force current below I_H. In AC circuits, natural commutation occurs at zero crossing.','{multiple_choice}'::text[],0.74) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-10','Varactor Diode Application','Medium','ECE','arena','select','Electronic Components','multiple_choice','A varactor (varicap) diode is used in VCO circuits because:','{"choices": ["It has very low forward voltage", "Its junction capacitance varies with reverse bias voltage — used to tune LC oscillator frequency electronically", "It rectifies AC signals with low loss", "It regulates voltage like a Zener"], "correct": 1}'::jsonb,'Varactor diode: C_j = C₀ / (1 + V_R/φ)^n. Capacitance decreases as reverse bias increases. In an LC VCO: f = 1/(2π√LC); adjusting V_R changes C_j and thus f. Used in FM tuners, PLLs, and frequency synthesisers.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-11','IGBT vs Power MOSFET Selection','Medium','ECE','arena','compare','Electronic Components','multiple_choice','An IGBT is preferred over a Power MOSFET for a 1200 V, 100 A motor drive application because:','{"choices": ["IGBTs have faster switching speed", "IGBTs have lower on-state voltage drop at high current and high voltage — MOSFET R_DS(on) scales poorly (R_DS(on) ∝ V_BR^2.5), making high-voltage MOSFETs lossy", "IGBTs are cheaper at low voltage", "IGBTs have simpler gate drive requirements"], "correct": 1}'::jsonb,'Above ~200 V, IGBT V_CE(sat) (≈2 V) is lower than MOSFET I×R_DS(on) at high voltage. IGBTs have bipolar conduction — minority carrier injection reduces on-state resistance. Trade-off: IGBT switching speed is slower (tail current from minority carrier recombination).','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-12','Electrolytic Capacitor Polarity','Medium','ECE','arena','diagnose','Electronic Components','multiple_choice','An electrolytic capacitor is accidentally reverse-biased in a DC circuit. What happens?','{"choices": ["Nothing — electrolytic caps are non-polar", "The capacitance increases", "The oxide layer breaks down, capacitor becomes low resistance, draws excessive current, heats up, and may rupture or explode", "The capacitor becomes an inductor"], "correct": 2}'::jsonb,'Electrolytic capacitors are polarised — the oxide layer (dielectric) is formed under correct polarity. Reverse bias destroys the oxide → capacitor becomes a short → massive current flow → gas generation → rupture (electrolytic caps have vent notches for this). Always observe polarity.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-13','Optocoupler: Isolation and CTR','Medium','ECE','arena','interpret','Electronic Components','multiple_choice','An optocoupler with CTR (current transfer ratio) = 100% is driven with I_F = 10 mA LED current. The maximum collector current I_C at the output is:','{"choices": ["0.1 mA", "10 mA", "100 mA", "1 A"], "correct": 1}'::jsonb,'CTR = I_C / I_F × 100%. CTR = 100% → I_C = I_F = 10 mA. Optocouplers provide galvanic isolation (typically 3500 V) between input and output. CTR varies with temperature, aging, and I_F level.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-14','Hall Effect Sensor vs Current Transformer','Medium','ECE','arena','compare','Electronic Components','multiple_choice','A Hall-effect current sensor (e.g., ACS712) measures current differently from a current transformer (CT) in that:','{"choices": ["Hall sensors only work with AC, CTs work with DC", "Hall sensors measure both AC and DC current (DC-capable), while CTs only work with AC current (they respond to dI/dt)", "CTs are more accurate at DC", "Hall sensors require physical wire break to install"], "correct": 1}'::jsonb,'Hall sensors use the magnetic field from current to produce a voltage proportional to current — they detect both AC and DC. CTs work by transformer action (induction) and require changing flux (AC only). Hall sensors: wider bandwidth but need power supply. CTs: passive and accurate for AC.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-15','Crystal Oscillator vs RC Oscillator','Medium','ECE','arena','compare','Electronic Components','multiple_choice','Crystal oscillators are preferred over RC oscillators for precision timing because:','{"choices": ["RC oscillators are more expensive", "Crystal Q factor is 10,000–1,000,000 vs RC oscillator Q < 1 — resulting in extremely high frequency stability (ppm range) vs RC (percent-level drift)", "Crystal oscillators use less power", "RC oscillators cannot operate above 1 MHz"], "correct": 1}'::jsonb,'Crystal Q factor (quality factor) is 10⁴–10⁶ → very sharp resonance → excellent frequency selectivity and stability. RC/LC oscillator Q ≈ 1–100 → broad resonance → frequency drifts with component tolerances and temperature.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-16','GaN Transistor Advantage Over Silicon','Hard','ECE','arena','compare','Electronic Components','multiple_choice','GaN (Gallium Nitride) power transistors offer advantages over silicon MOSFETs at high frequencies because:','{"choices": ["GaN has lower breakdown voltage", "GaN has zero gate capacitance", "GaN devices have lower gate charge (Q_g), zero reverse recovery charge (Q_rr), and higher electron mobility — enabling faster switching at lower switching losses for the same voltage/current rating", "GaN operates only at cryogenic temperatures"], "correct": 2}'::jsonb,'GaN HEMTs: 2DEG (two-dimensional electron gas) channel → high electron mobility → lower R_DS(on). No minority carriers → zero reverse recovery. Smaller Q_g → faster switching → suitable for MHz-range converters. Enable smaller, higher-efficiency PSUs (USB-C chargers).','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-17','MEMS Microphone vs Electret','Hard','ECE','arena','compare','Electronic Components','multiple_choice','MEMS microphones are increasingly preferred over electret condenser microphones (ECM) in smartphones because:','{"choices": ["MEMS have higher maximum SPL before clipping", "MEMS are manufactured in standard CMOS semiconductor process — enabling smaller size, tighter unit-to-unit matching, better temperature and humidity stability, and integration with amplifier/ADC on same chip", "MEMS require no power supply", "MEMS have lower self-noise"], "correct": 1}'::jsonb,'MEMS microphones: silicon membrane fabricated using photolithography → extreme dimensional consistency → ±1 dB sensitivity matching across units. Humidity stable (ECMs degrade). Reflow-solderable (ECMs can''t handle 260°C). Integrate ASIC on same die.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-18','SiC MOSFET Applications','Hard','ECE','arena','select','Electronic Components','multiple_choice','Silicon Carbide (SiC) MOSFETs are particularly suitable for:','{"choices": ["Consumer electronics under 12 V", "Audio amplifier applications", "High-voltage, high-temperature power conversion (600 V–1700 V) — EV inverters, solar inverters, railway traction — where SiC''s wide bandgap enables high temperature operation and low switching losses at high voltage", "RF power amplifiers above 10 GHz"], "correct": 2}'::jsonb,'SiC: bandgap 3.26 eV (Si: 1.12 eV) → higher breakdown field → thinner drift region → lower R_DS(on) for same voltage rating. T_J(max) = 200°C vs 150°C for Si. Critical for EV drive inverters (800 V bus, high efficiency needed).','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-19','Transient Voltage Suppressor (TVS) vs Zener','Hard','ECE','arena','compare','Electronic Components','multiple_choice','A TVS diode is used for ESD protection instead of a Zener diode because:','{"choices": ["TVS has higher breakdown voltage", "TVS is designed for microsecond/nanosecond response to fast transients and can absorb much higher peak pulse power (hundreds of watts) while Zener is rated for continuous DC regulation", "TVS has lower leakage current", "TVS is bidirectional only"], "correct": 1}'::jsonb,'TVS diodes: optimised junction area for high peak current capacity (P_PP up to 600 W for 10/1000 µs pulse), clamping response < 1 ps. Zener: designed for precision steady-state regulation, poor for transients. Use TVS for surge and ESD protection.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-20','Piezoelectric Transducer Operating Principle','Hard','ECE','arena','interpret','Electronic Components','multiple_choice','A piezoelectric ultrasonic transducer both transmits and receives sound because:','{"choices": ["The piezoelectric crystal has an internal oscillator", "Piezoelectric effect is reciprocal: applying voltage produces mechanical strain (transmit), and mechanical strain produces voltage (receive) — same crystal acts as both actuator and sensor", "The crystal has two separate elements", "Acoustic impedance matching enables bidirectionality"], "correct": 1}'::jsonb,'Direct piezoelectric effect: mechanical stress → electric charge. Inverse piezoelectric effect: electric field → mechanical strain. This reciprocity makes piezo crystals ideal as transceivers (ultrasound scanners, SONAR, ultrasonic range finders). Materials: PZT (lead zirconate titanate).','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-21','Phototransistor vs Photodiode Speed','Hard','ECE','arena','compare','Electronic Components','multiple_choice','A photodiode is preferred over a phototransistor in high-speed optical receivers (Gbps) because:','{"choices": ["Photodiodes have higher current output", "Photodiodes are cheaper", "Photodiode bandwidth is much higher — the transistor''s base capacitance and minority carrier transit time limit phototransistor bandwidth to typically < 1 MHz, while PIN photodiodes operate at > 1 GHz", "Phototransistors require higher bias voltage"], "correct": 2}'::jsonb,'Phototransistor = photodiode + BJT amplification. The transistor''s internal capacitances and minority carrier storage limit speed (τ ∝ β × τ_T). PIN photodiodes: intrinsic region depleted → very low junction capacitance → bandwidth > 1 GHz. Used in fibre optic receivers.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-22','Supercapacitor vs Battery Trade-offs','Hard','ECE','arena','compare','Electronic Components','multiple_choice','Supercapacitors (EDLC) are preferred over batteries for certain energy storage applications because:','{"choices": ["Supercapacitors have much higher energy density (Wh/kg)", "Supercapacitors can deliver very high peak currents with cycle life > 1 million — ideal for rapid charge/discharge cycles, pulse power, and buffering where batteries would degrade quickly", "Supercapacitors operate at higher voltages", "Supercapacitors are cheaper per joule stored"], "correct": 1}'::jsonb,'Supercapacitors: power density 10,000 W/kg vs battery 500 W/kg. Cycle life > 10⁶ (battery: 500–2000 cycles). Charge in seconds. However: energy density 5–10 Wh/kg vs battery 100–300 Wh/kg. Use for peak power buffering, start-stop systems, UPS ride-through.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-23','Ferrite Bead Impedance Characteristic','Hard','ECE','arena','interpret','Electronic Components','multiple_choice','A ferrite bead is used on a power supply line to filter high-frequency noise. Its impedance vs frequency plot shows: low impedance at DC/low frequency, peak impedance at ~100 MHz, then decreasing. This is because:','{"choices": ["Ferrite beads are high-pass filters", "At low frequency: resistive (low loss). Near resonant frequency: inductive (stores energy). Above resonant: capacitive (self-resonance from winding capacitance). The resistive region at 10–100 MHz dissipates EMI as heat — unlike LC filters which reflect it", "Ferrite beads are equivalent to resistors", "The peak impedance indicates the DC resistance"], "correct": 1}'::jsonb,'Ferrite beads are NOT inductors! They are dissipative filters. R component (loss) peaks at EMI frequencies (50–500 MHz), converting EMI to heat. Unlike reactive filters, they don''t create resonances with other capacitors. Select bead by impedance at target frequency.','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-24','DRAM Refresh Requirement','Hard','ECE','arena','interpret','Electronic Components','multiple_choice','DRAM cells must be refreshed every few milliseconds because:','{"choices": ["DRAM uses floating gate storage", "The capacitor-based storage cell slowly leaks charge due to leakage current of the access transistor and capacitor — data is lost within ~64 ms without refresh", "DRAM has destructive read — reading discharges the cell and data must be rewritten", "Both B and C"], "correct": 3}'::jsonb,'Both are true: (1) Capacitor charge leaks → refresh required every 64 ms typically. (2) DRAM read is destructive — sense amplifiers discharge the storage capacitor; data must be written back after every read. SRAM stores data in bistable flip-flops — no refresh, but larger (6T per bit).','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-ec-25','Reed Switch vs Hall Effect Switch','Hard','ECE','arena','compare','Electronic Components','multiple_choice','A Hall-effect switch is preferred over a reed switch in a high-vibration automotive application for position sensing because:','{"choices": ["Hall switches have higher magnetic sensitivity", "Reed switches are cheaper", "Hall switches have no moving parts — reed switch contacts can weld from arcing, fatigue from vibration, or bounce; Hall effect is solid-state with effectively unlimited mechanical life", "Reed switches require higher supply voltage"], "correct": 2}'::jsonb,'Reed switch: moving ferromagnetic contacts — susceptible to vibration-induced bounce, contact welding, contact oxidation over time, and mechanical fatigue. Hall switch: solid-state, no mechanical parts, virtually unlimited life, immune to vibration and shock. Automotive standard.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
